package kr.co.cudo.authoring.external.service;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import kr.co.cudo.authoring.batch.entity.LsDataLbl;
import kr.co.cudo.authoring.batch.entity.LsDataLblAiInfo;
import kr.co.cudo.authoring.batch.entity.LsDataMeta;
import kr.co.cudo.authoring.batch.entity.LsDataSrc;
import kr.co.cudo.authoring.batch.repository.LsDataLblAiInfoRepository;
import kr.co.cudo.authoring.batch.repository.LsDataLblRepository;
import kr.co.cudo.authoring.batch.repository.LsDataMetaRepository;
import kr.co.cudo.authoring.batch.repository.LsDataSrcRepository;
import kr.co.cudo.authoring.common.exception.CustomException;
import kr.co.cudo.authoring.common.exception.ErrorCode;
import kr.co.cudo.authoring.external.dto.DatasetResponse;
import kr.co.cudo.authoring.external.dto.FrameLabelInfo;
import kr.co.cudo.authoring.external.dto.LabelInfo;
import kr.co.cudo.authoring.external.dto.VideoInfo;
import kr.co.cudo.authoring.meta.entity.LsDataMetaReview;
import kr.co.cudo.authoring.meta.repository.LsDataMetaReviewRepository;
import kr.co.cudo.authoring.video.entity.LsDataRaw;
import kr.co.cudo.authoring.video.repository.VideoRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Phase 4 — 외부 학습데이터 API 빌더 서비스 (Phase 5/6 신규 테이블 정합화).
 *
 * <p>{@link #build(Long, boolean)} 은 영상(rawSn) 1건에 대해 다음 데이터를 조립한다.
 * <ul>
 *   <li>{@link VideoInfo} — LS_DATA_RAW 컬럼 중 시스템 식별·객관 메타만 (사용자 식별자 제외)</li>
 *   <li>메타 — {@code LS_DATA_META} 값 + {@code LS_DATA_META_REVIEW.META_TYPE_CD} 로 RAW/DEID 분류</li>
 *   <li>라벨 — {@code LS_DATA_SRC} 프레임 + 프레임의 {@code LS_DATA_LBL} + {@code LS_DATA_LBL_AI_INFO}</li>
 * </ul>
 *
 * <p>메타 분류 정책 (LS_DATA_META.METATYPE 컬럼 폐기 후):
 *  - LS_DATA_META_REVIEW.META_TYPE_CD == 'DEID' → deidMeta
 *  - 그 외 (review row 없음 포함, 'VLM'/'EXTERNAL'/'RAW' 등) → rawMeta
 *
 * <p>병합 정책: 같은 META_KEY 가 RAW 와 DEID 양쪽에 존재하면 RAW 가 우선한다.
 *
 * <p>프레임은 LS_DATA_SRC row 1건이 (RAW filePath + DEID srcBkupFilePath) 둘 다 보유하므로
 * 별도 분리 없이 RAW filePath 만 노출한다.
 *
 * <p>라벨 자동/신뢰도/출처는 LS_DATA_LBL_AI_INFO 와 단일 IN 쿼리로 join (N+1 회피).
 * AI 정보 row 가 없으면 수동 라벨로 간주 (autoGenerated=false / confidence=null / lblSrcCd=null).
 */
@Slf4j
@Service
@RequiredArgsConstructor
@Transactional(value = "controlTransactionManager", readOnly = true)
public class ExportApiService {

    private static final TypeReference<List<List<Double>>> POINTS_TYPE = new TypeReference<>() {};

    /** LS_DATA_META_REVIEW.META_TYPE_CD 값 — 외부 응답에서 비식별 메타로 분류한다. */
    static final String META_TYPE_DEID = "DEID";

    private final VideoRepository videoRepository;
    private final LsDataMetaRepository metaRepository;
    private final LsDataMetaReviewRepository metaReviewRepository;
    private final LsDataSrcRepository srcRepository;
    private final LsDataLblRepository lblRepository;
    private final LsDataLblAiInfoRepository lblAiInfoRepository;
    private final ObjectMapper objectMapper;

    public DatasetResponse build(Long rawSn, boolean merge) {
        LsDataRaw raw = videoRepository.findById(rawSn)
                .orElseThrow(() -> new CustomException(ErrorCode.NOT_FOUND,
                        "영상을 찾을 수 없습니다: rawSn=" + rawSn));

        VideoInfo video = VideoInfo.from(raw);

        // 메타: LS_DATA_META (값) + LS_DATA_META_REVIEW.META_TYPE_CD (분류)
        Map<String, String> rawMeta = new LinkedHashMap<>();
        Map<String, String> deidMeta = new LinkedHashMap<>();
        splitMeta(rawSn, rawMeta, deidMeta);

        List<FrameLabelInfo> frames = buildFrames(rawSn);

        log.info("[ExportApi] dataset built rawSn={}, frames={}, rawMeta={}, deidMeta={}, merge={}",
                rawSn, frames.size(), rawMeta.size(), deidMeta.size(), merge);

        if (merge) {
            Map<String, String> merged = mergeMeta(rawMeta, deidMeta);
            return DatasetResponse.merged(video, merged, frames);
        }
        return DatasetResponse.separated(video, rawMeta, deidMeta, frames);
    }

    /**
     * 메타를 RAW/DEID 로 분리한다.
     * <p>LS_DATA_META 전체를 조회한 뒤, LS_DATA_META_REVIEW.META_TYPE_CD == 'DEID' 인 row 만 deidMeta 로,
     * 그 외 (review 없음 포함) 는 rawMeta 로 분류한다.
     */
    private void splitMeta(Long rawSn, Map<String, String> rawMeta, Map<String, String> deidMeta) {
        List<LsDataMeta> metas = metaRepository.findByRawSn(rawSn);
        if (metas.isEmpty()) {
            return;
        }
        Map<Long, LsDataMetaReview> reviewMap = new HashMap<>();
        for (LsDataMetaReview r : metaReviewRepository.findAllByDataRawSn(rawSn)) {
            reviewMap.put(r.getDataMetaSn(), r);
        }
        for (LsDataMeta m : metas) {
            LsDataMetaReview r = reviewMap.get(m.getMetaSn());
            String type = (r != null) ? r.getMetaTypeCd() : null;
            if (META_TYPE_DEID.equalsIgnoreCase(type)) {
                deidMeta.put(m.getMetaKey(), m.getMetaVal());
            } else {
                rawMeta.put(m.getMetaKey(), m.getMetaVal());
            }
        }
    }

    /**
     * 영상의 RAW 프레임 + 각 프레임의 라벨을 frameNo 오름차순으로 조립.
     * <p>N+1 회피: 영상 전체 라벨을 단일 IN 쿼리로 조회 후 srcSn → labels 맵으로 그룹핑.
     * AI 정보 역시 단일 IN 쿼리로 lookup.
     */
    private List<FrameLabelInfo> buildFrames(Long rawSn) {
        List<LsDataSrc> frames = srcRepository.findByRawSnOrderByFrameNoAsc(rawSn);
        if (frames.isEmpty()) {
            return Collections.emptyList();
        }
        List<Long> srcSns = frames.stream().map(LsDataSrc::getSrcSn).toList();
        List<LsDataLbl> labels = lblRepository.findBySrcSnIn(srcSns);

        Map<Long, LsDataLblAiInfo> aiInfoByLblSn = Collections.emptyMap();
        if (!labels.isEmpty()) {
            List<Long> lblSns = labels.stream().map(LsDataLbl::getLblSn).toList();
            aiInfoByLblSn = new HashMap<>();
            for (LsDataLblAiInfo ai : lblAiInfoRepository.findByDataLblSnIn(lblSns)) {
                // dataLblSn 당 최신 1건 — 같은 라벨에 여러 row 가 있을 수는 없는 설계이나 방어적으로 putIfAbsent
                aiInfoByLblSn.putIfAbsent(ai.getDataLblSn(), ai);
            }
        }

        Map<Long, List<LabelInfo>> bySrc = new LinkedHashMap<>();
        for (LsDataLbl lbl : labels) {
            LsDataLblAiInfo ai = aiInfoByLblSn.get(lbl.getLblSn());
            LabelInfo info = LabelInfo.from(lbl, ai, parsePoints(lbl.getPointsJson()));
            bySrc.computeIfAbsent(lbl.getSrcSn(), k -> new ArrayList<>()).add(info);
        }
        return frames.stream()
                .map(s -> new FrameLabelInfo(
                        s.getFrameNo(),
                        s.getFilePath(),
                        bySrc.getOrDefault(s.getSrcSn(), Collections.emptyList())))
                .toList();
    }

    private List<List<Double>> parsePoints(String pointsJson) {
        if (pointsJson == null || pointsJson.isBlank()) {
            return Collections.emptyList();
        }
        try {
            return objectMapper.readValue(pointsJson, POINTS_TYPE);
        } catch (Exception e) {
            // 손상된 POINTS_JSON 은 외부 API 응답을 깨뜨리지 않도록 빈 배열로 안전 처리.
            log.warn("[ExportApi] points_json parse failed; returning empty array");
            return Collections.emptyList();
        }
    }

    /**
     * 메타 병합 — RAW 우선. 같은 key 가 양쪽에 있으면 RAW 의 값을 유지.
     * 결과 Map 순서는 RAW 먼저 → DEID 단독 key 추가 (LinkedHashMap).
     */
    private static Map<String, String> mergeMeta(Map<String, String> rawMeta,
                                                 Map<String, String> deidMeta) {
        Map<String, String> merged = new LinkedHashMap<>(rawMeta);
        for (Map.Entry<String, String> e : deidMeta.entrySet()) {
            merged.putIfAbsent(e.getKey(), e.getValue());
        }
        return merged;
    }
}
